package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

var (
	version = "a75b67b"
	commit  = "a75b67b73b9edb91dfc9f302dd108fa9d3ea5b05"
	built   = "2026-04-17 19:59 UTC by build.sh"
)

type Issue struct {
	Severity        string                 `json:"Severity"`
	Failure         string                 `json:"Failure"`
	RuleName        string                 `json:"RuleName"`
	Category        string                 `json:"Category"`
	Position        Position               `json:"Position"`
	Confidence      float64                `json:"Confidence"`
	ReplacementLine string                 `json:"ReplacementLine"`
}

type Position struct {
	Start Range `json:"Start"`
	End   Range `json:"End"`
}

type Range struct {
	Filename string `json:"Filename"`
	Offset   int    `json:"Offset"`
	Line     int    `json:"Line"`
	Column   int    `json:"Column"`
}

type Formatter interface {
	Format(issues []Issue) string
}

type DefaultFormatter struct{}

func (f *DefaultFormatter) Format(issues []Issue) string {
	var buf strings.Builder
	for _, issue := range issues {
		buf.WriteString(fmt.Sprintf("%s:%d:%d: %s\n",
			issue.Position.Start.Filename,
			issue.Position.Start.Line,
			issue.Position.Start.Column,
			issue.Failure))
	}
	return buf.String()
}

type JSONFormatter struct{}

func (f *JSONFormatter) Format(issues []Issue) string {
	if len(issues) == 0 {
		return "null\n"
	}
	data, _ := json.Marshal(issues)
	return string(data) + "\n"
}

type UnixFormatter struct{}

func (f *UnixFormatter) Format(issues []Issue) string {
	var buf strings.Builder
	for _, issue := range issues {
		buf.WriteString(fmt.Sprintf("%s:%d:%d: [%s] %s\n",
			issue.Position.Start.Filename,
			issue.Position.Start.Line,
			issue.Position.Start.Column,
			issue.RuleName,
			issue.Failure))
	}
	return buf.String()
}

type FriendlyFormatter struct{}

func (f *FriendlyFormatter) Format(issues []Issue) string {
	if len(issues) == 0 {
		return ""
	}

	var buf strings.Builder

	errors := 0
	warnings := 0
	ruleMap := make(map[string]int)

	for _, issue := range issues {
		if issue.Severity == "error" {
			errors++
		} else {
			warnings++
		}
		ruleMap[issue.RuleName]++
		buf.WriteString(fmt.Sprintf("  ⚠  https://revive.run/r#%s  %s\n",
			issue.RuleName, issue.Failure))
		buf.WriteString(fmt.Sprintf("  %s:%d:%d\n",
			issue.Position.Start.Filename,
			issue.Position.Start.Line,
			issue.Position.Start.Column))
	}

	buf.WriteString("\n")
	buf.WriteString(fmt.Sprintf("⚠ %d problem (%d errors, %d warning", len(issues), errors, warnings))
	if warnings != 1 {
		buf.WriteString("s")
	}
	buf.WriteString(")\n\n")

	if len(ruleMap) > 0 {
		buf.WriteString("Warnings:\n")
		i := 1
		for rule := range ruleMap {
			buf.WriteString(fmt.Sprintf("  %d  %s\n", i, rule))
			i++
		}
	}

	return buf.String()
}

type CheckstyleFormatter struct{}

func (f *CheckstyleFormatter) Format(issues []Issue) string {
	var buf strings.Builder
	buf.WriteString("<?xml version='1.0' encoding='UTF-8'?>\n")
	buf.WriteString("<checkstyle version=\"5.0\">\n")

	// Group by file
	fileMap := make(map[string][]Issue)
	for _, issue := range issues {
		fileMap[issue.Position.Start.Filename] = append(fileMap[issue.Position.Start.Filename], issue)
	}

	for file, fileIssues := range fileMap {
		buf.WriteString(fmt.Sprintf("  <file name=\"%s\">\n", file))
		for _, issue := range fileIssues {
			buf.WriteString(fmt.Sprintf("    <error line=\"%d\" column=\"%d\" severity=\"%s\" message=\"%s\" source=\"%s\" />\n",
				issue.Position.Start.Line,
				issue.Position.Start.Column,
				issue.Severity,
				issue.Failure,
				issue.RuleName))
		}
		buf.WriteString("  </file>\n")
	}

	buf.WriteString("</checkstyle>\n")
	return buf.String()
}

type SARIFFormatter struct{}

func (f *SARIFFormatter) Format(issues []Issue) string {
	rules := make([]map[string]interface{}, 0)
	ruleMap := make(map[string]bool)

	for _, issue := range issues {
		if !ruleMap[issue.RuleName] {
			ruleMap[issue.RuleName] = true
			rules = append(rules, map[string]interface{}{
				"id":       issue.RuleName,
				"helpUri":  fmt.Sprintf("https://revive.run/r#%s", issue.RuleName),
				"properties": map[string]string{
					"severity": issue.Severity,
				},
			})
		}
	}

	results := make([]map[string]interface{}, 0)
	for _, issue := range issues {
		results = append(results, map[string]interface{}{
			"ruleId":  issue.RuleName,
			"message": map[string]string{"text": issue.Failure},
			"locations": []map[string]interface{}{
				{
					"physicalLocation": map[string]interface{}{
						"artifactLocation": map[string]string{"uri": issue.Position.Start.Filename},
						"region": map[string]int{
							"startLine":   issue.Position.Start.Line,
							"startColumn": issue.Position.Start.Column,
						},
					},
				},
			},
		})
	}

	sarif := map[string]interface{}{
		"version": "2.1.0",
		"runs": []map[string]interface{}{
			{
				"tool": map[string]interface{}{
					"driver": map[string]interface{}{
						"name":             "revive",
						"informationUri":   "https://revive.run",
						"rules":            rules,
					},
				},
				"results": results,
			},
		},
	}

	data, _ := json.MarshalIndent(sarif, "", "  ")
	return string(data) + "\n"
}

type NDJsonFormatter struct{}

func (f *NDJsonFormatter) Format(issues []Issue) string {
	var buf strings.Builder
	for _, issue := range issues {
		data, _ := json.Marshal(issue)
		buf.WriteString(string(data) + "\n")
	}
	return buf.String()
}

type PlainFormatter struct{}

func (f *PlainFormatter) Format(issues []Issue) string {
	return (&DefaultFormatter{}).Format(issues)
}

type StylishFormatter struct{}

func (f *StylishFormatter) Format(issues []Issue) string {
	return ""
}

func getFormatter(name string) Formatter {
	switch name {
	case "json":
		return &JSONFormatter{}
	case "unix":
		return &UnixFormatter{}
	case "friendly":
		return &FriendlyFormatter{}
	case "checkstyle":
		return &CheckstyleFormatter{}
	case "sarif":
		return &SARIFFormatter{}
	case "ndjson":
		return &NDJsonFormatter{}
	case "plain":
		return &PlainFormatter{}
	case "stylish":
		return &StylishFormatter{}
	default:
		return &DefaultFormatter{}
	}
}

func checkPackageComment(filename string, fset *token.FileSet, f *ast.File) []Issue {
	var issues []Issue

	// Check if there's a package comment
	if f.Doc == nil {
		file := fset.File(f.Pos())
		issues = append(issues, Issue{
			Severity:        "warning",
			Failure:         "should have a package comment",
			RuleName:        "package-comments",
			Category:        "comments",
			Position: Position{
				Start: Range{
					Filename: filename,
					Offset:   0,
					Line:     1,
					Column:   1,
				},
				End: Range{
					Filename: filename,
					Offset:   12,
					Line:     1,
					Column:   13,
				},
			},
			Confidence:      1.0,
			ReplacementLine: "",
		})
	}

	return issues
}

func lintFile(filename string, rules map[string]bool) []Issue {
	content, err := os.ReadFile(filename)
	if err != nil {
		return nil
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, string(content), parser.ParseComments)
	if err != nil {
		return nil
	}

	var issues []Issue

	// Apply rules if not disabled
	if !rules["package-comments"] {
		issues = append(issues, checkPackageComment(filename, fset, f)...)
	}

	return issues
}

func shouldExclude(path string, excludes []string) bool {
	for _, pattern := range excludes {
		if matched, _ := filepath.Match(pattern, path); matched {
			return true
		}
		if matched, _ := filepath.Match(pattern, filepath.Base(path)); matched {
			return true
		}
	}
	return false
}

func getGoFiles(paths []string, excludes []string) []string {
	var files []string

	for _, path := range paths {
		path = strings.TrimSuffix(path, "/...")

		if strings.HasSuffix(path, ".go") {
			if !shouldExclude(path, excludes) {
				files = append(files, path)
			}
		} else {
			// Directory
			filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}

				if !info.IsDir() && strings.HasSuffix(p, ".go") {
					if !shouldExclude(p, excludes) {
						files = append(files, p)
					}
				}
				return nil
			})
		}
	}

	return files
}

func main() {
	configFlag := flag.String("config", "", "path to the configuration TOML file")
	formatterFlag := flag.String("formatter", "default", "formatter to be used for the output")
	versionFlag := flag.Bool("version", false, "get revive version")
	setExitStatusFlag := flag.Bool("set_exit_status", false, "set exit status to 1 if any issues are found")
	maxOpenFilesFlag := flag.Int("max_open_files", 0, "maximum number of open files at the same time")

	// Handle exclude as a slice
	var excludes []string
	flag.Func("exclude", "list of globs which specify files to be excluded", func(s string) error {
		excludes = append(excludes, s)
		return nil
	})

	flag.Parse()

	if *versionFlag {
		fmt.Printf("Version:\t%s\n", version)
		fmt.Printf("Commit:\t\t%s\n", commit)
		fmt.Printf("Built\t\t%s\n", built)
		return
	}

	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Determine which rules to use
	rules := map[string]bool{
		"package-comments": true,
	}

	// If config file is specified, parse it and disable rules
	if *configFlag != "" {
		// For now, we'll parse basic TOML to disable rules
		// A full implementation would use a TOML parser
		content, err := os.ReadFile(*configFlag)
		if err == nil {
			configStr := string(content)
			if strings.Contains(configStr, "package-comments") && strings.Contains(configStr, "disabled") {
				rules["package-comments"] = false
			}
		}
	}

	files := getGoFiles(paths, excludes)

	var allIssues []Issue
	for _, file := range files {
		issues := lintFile(file, rules)
		allIssues = append(allIssues, issues...)
	}

	formatter := getFormatter(*formatterFlag)
	output := formatter.Format(allIssues)
	fmt.Print(output)

	if *setExitStatusFlag && len(allIssues) > 0 {
		os.Exit(1)
	}
}
EOF

