	if *configFlag != "" {
		// For now, we'll parse basic TOML to disable rules
		// A full implementation would use a TOML parser
		content, err := os.ReadFile(*configFlag)
		if err == nil {
			configStr := string(content)
			if strings.Contains(configStr, "package-comments") && strings.Contains(configStr, "disabled") {
				rules["package-comments"] = false
			}
		}
	}

	files := getGoFiles(paths, excludes)

	var allIssues []Issue
	for _, file := range files {
		issues := lintFile(file, rules)
		allIssues = append(allIssues, issues...)
	}

