	if len(issues) == 0 {
		return "null\n"
	}
	data, _ := json.Marshal(issues)
	return string(data) + "\n"
}

type UnixFormatter struct{}

func (f *UnixFormatter) Format(issues []Issue) string {
	var buf strings.Builder
	for _, issue := range issues {
		buf.WriteString(fmt.Sprintf("%s:%d:%d: [%s] %s\n",
			issue.Position.Start.Filename,
			issue.Position.Start.Line,
			issue.Position.Start.Column,
			issue.RuleName,
			issue.Failure))
	}
	return buf.String()
}

type FriendlyFormatter struct{}

func (f *FriendlyFormatter) Format(issues []Issue) string {
	if len(issues) == 0 {
		return ""
	}

	var buf strings.Builder

	errors := 0
	warnings := 0
	ruleMap := make(map[string]int)

	for _, issue := range issues {
		if issue.Severity == "error" {
			errors++
		} else {
			warnings++
		}
		ruleMap[issue.RuleName]++
		buf.WriteString(fmt.Sprintf("  ⚠  https://revive.run/r#%s  %s\n",
			issue.RuleName, issue.Failure))
		buf.WriteString(fmt.Sprintf("  %s:%d:%d\n",
			issue.Position.Start.Filename,
			issue.Position.Start.Line,
			issue.Position.Start.Column))
	}

	buf.WriteString("\n")
	buf.WriteString(fmt.Sprintf("⚠ %d problem (%d errors, %d warning", len(issues), errors, warnings))
	if warnings != 1 {
		buf.WriteString("s")
	}
	buf.WriteString(")\n\n")

	if len(ruleMap) > 0 {
		buf.WriteString("Warnings:\n")
		i := 1
		for rule := range ruleMap {
			buf.WriteString(fmt.Sprintf("  %d  %s\n", i, rule))
			i++
		}
	}

	return buf.String()
}

type CheckstyleFormatter struct{}

func (f *CheckstyleFormatter) Format(issues []Issue) string {
	var buf strings.Builder
	buf.WriteString("<?xml version='1.0' encoding='UTF-8'?>\n")
	buf.WriteString("<checkstyle version=\"5.0\">\n")

	// Group by file
	fileMap := make(map[string][]Issue)
	for _, issue := range issues {
		fileMap[issue.Position.Start.Filename] = append(fileMap[issue.Position.Start.Filename], issue)
	}

	for file, fileIssues := range fileMap {
		buf.WriteString(fmt.Sprintf("  <file name=\"%s\">\n", file))
		for _, issue := range fileIssues {
			buf.WriteString(fmt.Sprintf("    <error line=\"%d\" column=\"%d\" severity=\"%s\" message=\"%s\" source=\"%s\" />\n",
				issue.Position.Start.Line,
				issue.Position.Start.Column,
				issue.Severity,
				issue.Failure,
				issue.RuleName))
		}
		buf.WriteString("  </file>\n")
	}

	buf.WriteString("</checkstyle>\n")
	return buf.String()
}

