func checkPackageComment(filename string, fset *token.FileSet, f *ast.File) []Issue {
	var issues []Issue

	// Check if there's a package comment
	if f.Doc == nil {
		issues = append(issues, Issue{
			Severity:        "warning",
			Failure:         "should have a package comment",
			RuleName:        "package-comments",
			Category:        "comments",
			Position: Position{
				Start: Range{
					Filename: filename,
					Offset:   0,
					Line:     1,
					Column:   1,
				},
				End: Range{
					Filename: filename,
					Offset:   12,
					Line:     1,
					Column:   13,
				},
			},
			Confidence:      1.0,
			ReplacementLine: "",
		})
	}

	return issues
}

func lintFile(filename string, rules map[string]bool) []Issue {
	content, err := os.ReadFile(filename)
	if err != nil {
		return nil
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, string(content), parser.ParseComments)
	if err != nil {
		return nil
	}

	var issues []Issue

	// Apply rules if enabled
	if rules["package-comments"] {
		issues = append(issues, checkPackageComment(filename, fset, f)...)
	}

	return issues
}

func shouldExclude(path string, excludes []string) bool {
	for _, pattern := range excludes {
		if matched, _ := filepath.Match(pattern, path); matched {
			return true
		}
		if matched, _ := filepath.Match(pattern, filepath.Base(path)); matched {
			return true
		}
	}
	return false
}

func getGoFiles(paths []string, excludes []string) []string {
	var files []string

	for _, path := range paths {
		path = strings.TrimSuffix(path, "/...")

		if strings.HasSuffix(path, ".go") {
			if !shouldExclude(path, excludes) {
				files = append(files, path)
			}
		} else {
			// Directory
			filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}

				if !info.IsDir() && strings.HasSuffix(p, ".go") {
					if !shouldExclude(p, excludes) {
						files = append(files, p)
					}
				}
				return nil
			})
		}
	}

	return files
}

func main() {
	configFlag := flag.String("config", "", "path to the configuration TOML file")
	formatterFlag := flag.String("formatter", "default", "formatter to be used for the output")
	versionFlag := flag.Bool("version", false, "get revive version")
	setExitStatusFlag := flag.Bool("set_exit_status", false, "set exit status to 1 if any issues are found")
	_ = flag.Int("max_open_files", 0, "maximum number of open files at the same time")

	// Handle exclude as a slice
	var excludes []string
	flag.Func("exclude", "list of globs which specify files to be excluded", func(s string) error {
		excludes = append(excludes, s)
		return nil
	})

	flag.Parse()

	if *versionFlag {
		fmt.Printf("Version:\t%s\n", version)
		fmt.Printf("Commit:\t\t%s\n", commit)
		fmt.Printf("Built\t\t%s\n", built)
		return
	}

	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Determine which rules to use - all enabled by default
	rules := map[string]bool{
		"package-comments": true,
	}

	// If config file is specified, parse it and disable rules
	if *configFlag != "" {
		// For now, we'll parse basic TOML to disable rules
		// A full implementation would use a TOML parser
		content, err := os.ReadFile(*configFlag)
		if err == nil {
			configStr := string(content)
			if strings.Contains(configStr, "package-comments") && strings.Contains(configStr, "disabled") {
				rules["package-comments"] = false
			}
		}
	}

	files := getGoFiles(paths, excludes)

	var allIssues []Issue
	for _, file := range files {
		issues := lintFile(file, rules)
		allIssues = append(allIssues, issues...)
	}

	formatter := getFormatter(*formatterFlag)
	output := formatter.Format(allIssues)
	fmt.Print(output)

	if *setExitStatusFlag && len(allIssues) > 0 {
		os.Exit(1)
	}
}
