	var allIssues []Issue
	for _, file := range files {
		issues := lintFile(file, rules)
		allIssues = append(allIssues, issues...)
	}

	formatter := getFormatter(*formatterFlag)
	output := formatter.Format(allIssues)
	fmt.Print(output)

	if *setExitStatusFlag && len(allIssues) > 0 {
		os.Exit(1)
	}
}
